const LANGUAGE_SWITCH_SCROLL_KEY = "language-switch-scroll";
const MAX_AGE_MS = 15000;

type LanguageSwitchScrollState = {
  pathname: string;
  scrollY: number;
  timestamp: number;
};

export function saveLanguageSwitchScrollState() {
  if (typeof window === "undefined") {
    return;
  }

  const state: LanguageSwitchScrollState = {
    pathname: window.location.pathname,
    scrollY: window.scrollY,
    timestamp: Date.now(),
  };

  window.sessionStorage.setItem(
    LANGUAGE_SWITCH_SCROLL_KEY,
    JSON.stringify(state)
  );
}

export function restoreLanguageSwitchScrollState() {
  if (typeof window === "undefined") {
    return false;
  }

  const rawState = window.sessionStorage.getItem(LANGUAGE_SWITCH_SCROLL_KEY);
  if (!rawState) {
    return false;
  }

  window.sessionStorage.removeItem(LANGUAGE_SWITCH_SCROLL_KEY);

  try {
    const state = JSON.parse(rawState) as LanguageSwitchScrollState;

    if (Date.now() - state.timestamp > MAX_AGE_MS) {
      return false;
    }

    window.scrollTo(0, Math.max(state.scrollY, 0));
    return true;
  } catch {
    return false;
  }
}
