type AnalyticsParams = Record<string, string | number | boolean | undefined>;
const GA_TRACKING_ID = "G-B09Y6PL7JC";
let analyticsLoadPromise: Promise<void> | null = null;
let analyticsStarted = false;

declare global {
  interface Window {
    dataLayer?: unknown[][];
    gtag?: (...args: unknown[]) => void;
  }
}

function ensureGtagStub() {
  if (typeof window === "undefined") {
    return;
  }

  window.dataLayer = window.dataLayer || [];

  if (typeof window.gtag !== "function") {
    window.gtag = (...args: unknown[]) => {
      window.dataLayer?.push(args);
    };
  }
}

export function isAnalyticsStarted() {
  return analyticsStarted;
}

export function loadAnalytics() {
  if (typeof window === "undefined") {
    return Promise.resolve();
  }

  if (analyticsLoadPromise) {
    return analyticsLoadPromise;
  }

  analyticsStarted = true;
  ensureGtagStub();

  window.gtag?.("js", new Date());
  window.gtag?.("config", GA_TRACKING_ID, {
    anonymize_ip: true,
    cookie_expires: 0,
    send_page_view: false,
  });

  analyticsLoadPromise = new Promise<void>((resolve, reject) => {
    const existingScript = document.querySelector<HTMLScriptElement>(
      `script[src="https://www.googletagmanager.com/gtag/js?id=${GA_TRACKING_ID}"]`
    );

    if (existingScript) {
      resolve();
      return;
    }

    const script = document.createElement("script");
    script.async = true;
    script.src = `https://www.googletagmanager.com/gtag/js?id=${GA_TRACKING_ID}`;
    script.onload = () => resolve();
    script.onerror = () => {
      analyticsLoadPromise = null;
      reject(new Error("Unable to load Google Analytics"));
    };
    document.head.appendChild(script);
  });

  return analyticsLoadPromise;
}

export function trackPageView(pathname: string) {
  if (typeof window === "undefined" || typeof window.gtag !== "function") {
    return;
  }

  window.gtag("event", "page_view", {
    page_path: pathname,
    page_location: window.location.href,
    page_title: document.title,
  });
}

export function trackEvent(eventName: string, params: AnalyticsParams = {}) {
  if (typeof window === "undefined") {
    return;
  }

  void loadAnalytics();
  window.gtag?.("event", eventName, params);
}
