import React, { ReactNode } from "react";
import { useLocation } from "@reach/router";
import { Link } from "gatsby";
import { UserProfile } from "../interfaces";
import Navigation from "../components/nav";
import AnalyticsBootstrap from "../components/analyticsBootstrap";
import { AuditRequestModalProvider } from "../components/auditRequestModal";
import { useTranslation, useI18next } from "gatsby-plugin-react-i18next";
import data from "../data/data.json";
import { restoreLanguageSwitchScrollState } from "../utils/languageScroll";
import { trackEvent } from "../utils/analytics";

interface LayoutProps {
  children: ReactNode;
  data?: UserProfile;
  hideChromeOnPrint?: boolean;
}

interface FooterContent {
  followUs: string;
  resumeEn: string;
  resumeFr: string;
}

const userData: UserProfile = data;

const Layout: React.FC<LayoutProps> = ({
  children,
  data,
  hideChromeOnPrint = false,
}) => {
  const { t } = useTranslation();
  const { language } = useI18next();
  const location = useLocation();
  const footerContent: FooterContent = t(
    "footer",
    { returnObjects: true }
  ) || { followUs: "", resumeEn: "", resumeFr: "" };
  const [currentYear, setYear] = React.useState<number | null>(null);
  const resumeLinks = [
    { href: "/en/resume/", label: footerContent.resumeEn },
    { href: "/fr/resume/", label: footerContent.resumeFr },
  ];

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);

  React.useEffect(() => {
    if (typeof window === "undefined") {
      return undefined;
    }

    let frameOne = 0;
    let frameTwo = 0;

    frameOne = window.requestAnimationFrame(() => {
      frameTwo = window.requestAnimationFrame(() => {
        restoreLanguageSwitchScrollState();
      });
    });

    return () => {
      window.cancelAnimationFrame(frameOne);
      window.cancelAnimationFrame(frameTwo);
    };
  }, [location.pathname]);

  return (
    <AuditRequestModalProvider>
      <>
        <AnalyticsBootstrap />
        <div
          className={`fixed inset-0 bg-no-repeat bg-cover bg-center before:content-[''] before:absolute before:inset-0 before:bg-white/80 ${
            hideChromeOnPrint ? "print:hidden" : ""
          }`}
        ></div>
        <div id={data?.menu[0]}>
          <Navigation />
          <div className="relative">{children}</div>
        </div>

        <footer className="site-footer" id={userData.menu[4]}>
          <div className="footer-inner">

            {/* Top: brand + nav links */}
            <div className="footer-top">
              <div>
                <p className="footer-brand-name">Juan Pablo Riaño</p>
                <p className="footer-brand-meta">UI/UX · Frontend · Montréal (ET)</p>
              </div>
              <nav className="footer-nav" aria-label="Footer navigation">
                <Link to={`/${language}/services/`}>{t("menu.services")}</Link>
                <Link to={`/${language}/portfolio/`}>{t("menu.portfolio")}</Link>
                <Link to={`/${language}/about/`}>{t("menu.about")}</Link>
                <Link to={`/${language}/contact/`}>{t("menu.contact")}</Link>
              </nav>
            </div>

            {/* Mid: contact links */}
            <div className="footer-mid">
              <a
                href={`mailto:${userData.email}`}
                className="footer-contact-link"
                onClick={() => trackEvent("contact_email_click", { source: "footer.email" })}
              >
                {userData.email}
              </a>
              <span className="footer-sep">·</span>
              <a
                href={userData.linkedIn}
                target="_blank"
                rel="noreferrer"
                className="footer-contact-link"
                aria-label="LinkedIn"
              >
                LinkedIn
              </a>
              <span className="footer-sep">·</span>
              <a
                href={userData.github}
                target="_blank"
                rel="noreferrer"
                className="footer-contact-link"
                aria-label="GitHub"
              >
                GitHub
              </a>
              <span className="footer-sep">·</span>
              <a
                href={userData.whatsapp}
                target="_blank"
                rel="noreferrer"
                className="footer-contact-link"
              >
                WhatsApp
              </a>
            </div>

            {/* Bottom: copyright + resume links */}
            <div className="footer-bottom">
              <p className="footer-copy">
                &copy; {currentYear ?? new Date().getFullYear()} Juan Pablo Riano
              </p>
              <div className="footer-resume">
                {resumeLinks.map((item) => (
                  <Link key={item.href} to={item.href}>{item.label}</Link>
                ))}
              </div>
            </div>

          </div>
        </footer>
      </>
    </AuditRequestModalProvider>
  );
};

export default Layout;

