import * as React from "react";
import { useLocation } from "@reach/router";
import {
  isAnalyticsStarted,
  loadAnalytics,
  trackPageView,
} from "../utils/analytics";

const START_EVENTS: Array<keyof WindowEventMap> = [
  "pointerdown",
  "keydown",
  "touchstart",
  "scroll",
];

export default function AnalyticsBootstrap() {
  const location = useLocation();
  const currentPath = `${location.pathname}${location.search}${location.hash}`;
  const latestPathRef = React.useRef(currentPath);

  React.useEffect(() => {
    latestPathRef.current = currentPath;

    if (isAnalyticsStarted()) {
      trackPageView(currentPath);
    }
  }, [currentPath]);

  React.useEffect(() => {
    if (typeof window === "undefined" || isAnalyticsStarted()) {
      return undefined;
    }

    let timeoutId = 0;

    const startAnalytics = () => {
      START_EVENTS.forEach((eventName) => {
        window.removeEventListener(eventName, startAnalytics);
      });

      window.clearTimeout(timeoutId);
      void loadAnalytics().finally(() => {
        trackPageView(latestPathRef.current);
      });
    };

    START_EVENTS.forEach((eventName) => {
      window.addEventListener(eventName, startAnalytics, {
        once: true,
        passive: true,
      });
    });

    timeoutId = window.setTimeout(startAnalytics, 2500);

    return () => {
      START_EVENTS.forEach((eventName) => {
        window.removeEventListener(eventName, startAnalytics);
      });
      window.clearTimeout(timeoutId);
    };
  }, []);

  return null;
}
